"use client";

import { useState } from "react";

export default function Home() {
  const [data, setData] = useState<string>("");
  const [fragmentSize, setFragmentSize] = useState<number>(16);
  const [encryptionKey, setEncryptionKey] = useState<string>("");
  const [fragments, setFragments] = useState<{ index: number; encryptedData: string }[]>([]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch("/api/fragmentData", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ data, fragmentSize, encryptionKey }),
      });

      if (!response.ok) {
        console.error("Error:", await response.json());
        return;
      }

      const result = await response.json();
      setFragments(result.fragments);
    } catch (error) {
      console.error("Error fragmenting data:", error);
    }
  };

  return (
    <div style={{ padding: "20px", fontFamily: "Arial, sans-serif" }}>
      <h1>Data Fragmentation and Encryption</h1>
      <form onSubmit={handleSubmit} style={{ marginBottom: "20px" }}>
        <div>
          <label>
            Data:
            <textarea
              value={data}
              onChange={(e) => setData(e.target.value)}
              rows={4}
              cols={50}
              placeholder="Enter the data to be fragmented"
              required
            />
          </label>
        </div>
        <div>
          <label>
            Fragment Size:
            <input
              type="number"
              value={fragmentSize}
              onChange={(e) => setFragmentSize(Number(e.target.value))}
              required
              min={1}
            />
          </label>
        </div>
        <div>
          <label>
            Encryption Key:
            <input
              type="text"
              value={encryptionKey}
              onChange={(e) => setEncryptionKey(e.target.value)}
              required
              placeholder="Enter an encryption key"
            />
          </label>
        </div>
        <button type="submit">Fragment and Encrypt</button>
      </form>

      {fragments.length > 0 && (
        <div>
          <h2>Fragments</h2>
          <pre>{JSON.stringify(fragments, null, 2)}</pre>
        </div>
      )}
    </div>
  );
}
